<section class="card" id="stockissue-form" tabindex="-1"><h2>Report / Request Non-Sale Issue</h2>
<?php if(!$extraId):?><form method="get"><input type="hidden" name="page" value="new"><label>Stock Item *<select name="extra_id" required><option value="">Choose Tracked Stock</option><?php foreach($options as $p):?><option value="<?=(int)$p['item']['id']?>"><?=access_h($p['item']['name'])?> · Available <?=si_qty($p['available'])?></option><?php endforeach?></select></label><div class="si-actions"><button type="submit">Continue</button></div></form>
<?php else:$selected=null;foreach($options as $p)if((int)$p['item']['id']===$extraId)$selected=$p;if(!$selected):?><p>This item is unavailable for new stock reports.</p><?php else:$p=$selected;?>
<div class="si-row"><h3><?=access_h($p['item']['name'])?></h3><?php si_link('Change Item',['page'=>'new']);?></div><dl class="si-totals"><?php foreach(['on_hand'=>'Recorded On Hand','held'=>'Held From Sale','available'=>'Available For Sale'] as $n=>$label):?><div><dt><?=$label?></dt><dd><?=si_qty($p[$n])?></dd></div><?php endforeach?></dl>
<form method="post" enctype="multipart/form-data" id="stockissue-report" data-available="<?=$p['available']?>" data-held="<?=$p['held']?>" data-stock="<?=$p['on_hand']?>" data-confirm="Submit this stock issue once and hold the stated quantity from sale for admin review?"><?php si_fields('report',['extra_id'=>(string)$extraId]);?>
<div class="si-grid"><label>Reason *<select name="kind" required><?php foreach(\Tivoli\Service\StockIssueService::KINDS as $value=>$label):?><option value="<?=$value?>" <?=si_value('kind','damage')===$value?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label>Quantity *<input name="qty" type="number" min="0.01" step="0.01" required value="<?=access_h(si_value('qty','1.00'))?>"></label>
<label>Current Position *<select name="position"><option value="held" <?=si_value('position','held')==='held'?'selected':''?>>Still Held / Not Yet Supplied</option><option value="gone" <?=si_value('position')==='gone'?'selected':''?>>Already Disposed / Supplied / Missing</option><option value="counted" <?=si_value('position')==='counted'?'selected':''?>>Already Deducted By Approved Count</option></select></label>
<label>Actual Incident / Finding / Request Time (UTC) *<input type="datetime-local" name="actual_at" step="1" required max="<?=gmdate('Y-m-d\TH:i:s')?>" value="<?=access_h(si_value('actual_at',gmdate('Y-m-d\TH:i:s')))?>"></label>
<label id="stockissue-count" hidden>Linked Approved Count *<select name="count_id" disabled><option value="">Choose Exact Approved Loss</option><?php foreach($counts as $count):?><option value="<?=$count['id']?>" data-qty="<?=si_qty($count['qty'])?>" data-time="<?=access_h(str_replace(' ','T',$count['at']))?>" data-kind="<?=access_h(match($count['reason']){'Damage'=>'damage','Expiry'=>'expiry',default=>'missing'})?>" <?=si_value('count_id')===(string)$count['id']?'selected':''?>>#<?=$count['id']?> · <?=access_h($count['reason'])?> · <?=si_qty($count['qty'])?> Already Deducted</option><?php endforeach?></select><small>Only the exact full loss from a supported approved count may be linked once.</small></label>
<?php si_upload();?></div><?php si_text('Comment');?>
<div class="si-preview" id="stockissue-preview" aria-live="polite"></div><?php si_check('I checked the item, quantity and actual position.');?>
<div class="si-actions"><button type="submit">Submit For Admin Review</button><?php si_link('Cancel');?></div></form><?php endif;endif?></section>
